/**
 * OpenAPI 3.x → TypeScript Connector Package Codegen
 *
 * Accepts an OpenAPI 3.x spec (JSON or YAML) and emits a full connector package:
 *   connector.json        — SoT manifest generated from the spec
 *   src/connector.ts      — DataSourceClient subclass
 *   src/operations/*.ts   — one file per operation
 *   tsconfig.json         — CommonJS (R-CJS)
 *   package.json
 *
 * All generated files include a `// @generated` header.
 * SSRF validation (R-SSRF) is enforced at generation time — generation fails
 * if any server URL resolves to a forbidden CIDR or wildcard.
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";

import { parse as parseYaml } from "yaml";

import { assertNoPathTraversal } from "./init-path.js";
import { validateConnectorManifest, validateSsrfAllowedDomains } from "./mcp-manifest.js";

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const GENERATED_HEADER =
  "// @generated by galaxy-cli — do not edit manually; custom changes preserved on re-run via merge markers";

const GENERATED_BLOCK_START = "// @generated:start";
const GENERATED_BLOCK_END = "// @generated:end";

const MANIFEST_FILENAME = "connector.json";

// ---------------------------------------------------------------------------
// OpenAPI types (minimal subset for codegen)
// ---------------------------------------------------------------------------

interface OpenApiServer {
  url: string;
  description?: string;
}

interface OpenApiSchema {
  type?: string;
  properties?: Record<string, OpenApiSchema>;
  required?: string[];
  items?: OpenApiSchema;
  description?: string;
  // Allow pass-through for any additional schema keywords
  [key: string]: unknown;
}

interface OpenApiParameter {
  name: string;
  in: "query" | "path" | "header" | "cookie";
  description?: string;
  required?: boolean;
  schema?: OpenApiSchema;
}

interface OpenApiRequestBody {
  description?: string;
  content?: Record<string, { schema?: OpenApiSchema }>;
}

interface OpenApiResponse {
  description?: string;
  content?: Record<string, { schema?: OpenApiSchema }>;
}

interface OpenApiOperation {
  operationId?: string;
  summary?: string;
  description?: string;
  parameters?: OpenApiParameter[];
  requestBody?: OpenApiRequestBody;
  responses?: Record<string, OpenApiResponse>;
  tags?: string[];
}

interface OpenApiPathItem {
  parameters?: OpenApiParameter[];
  get?: OpenApiOperation;
  post?: OpenApiOperation;
  put?: OpenApiOperation;
  patch?: OpenApiOperation;
  delete?: OpenApiOperation;
}

interface OpenApiDocument {
  openapi: string;
  info: {
    title: string;
    version: string;
    description?: string;
  };
  servers?: OpenApiServer[];
  paths?: Record<string, OpenApiPathItem>;
}

// ---------------------------------------------------------------------------
// Connector manifest types
// ---------------------------------------------------------------------------

export interface ConnectorOperationDef {
  description?: string;
  requestSchema?: Record<string, unknown>;
  responseSchema?: Record<string, unknown>;
}

// ---------------------------------------------------------------------------
// Parsing
// ---------------------------------------------------------------------------

/**
 * Parse an OpenAPI 3.x spec from a JSON or YAML file.
 * Returns a plain object — caller validates the structure.
 */
export function parseOpenApiSpec(specPath: string): OpenApiDocument {
  const resolvedPath = path.resolve(specPath);
  let content: string;
  try {
    content = readFileSync(resolvedPath, "utf-8");
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    throw new Error(`Cannot read OpenAPI spec at "${resolvedPath}": ${msg}`);
  }

  let raw: unknown;
  const ext = path.extname(resolvedPath).toLowerCase();
  if (ext === ".json") {
    try {
      raw = JSON.parse(content);
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      throw new Error(`Invalid JSON in spec file "${resolvedPath}": ${msg}`);
    }
  } else {
    // YAML (or .yml)
    try {
      raw = parseYaml(content);
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      throw new Error(`Invalid YAML in spec file "${resolvedPath}": ${msg}`);
    }
  }

  if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
    throw new Error(`OpenAPI spec "${resolvedPath}" must be a JSON/YAML object, got ${typeof raw}`);
  }

  const doc = raw as Record<string, unknown>;

  if (typeof doc["openapi"] !== "string" || !doc["openapi"].startsWith("3.")) {
    throw new Error(
      `OpenAPI spec "${resolvedPath}" must be OpenAPI 3.x (found openapi: "${String(doc["openapi"])}")`
    );
  }

  if (typeof doc["info"] !== "object" || doc["info"] === null) {
    throw new Error(`OpenAPI spec "${resolvedPath}" is missing the required "info" object`);
  }

  return raw as OpenApiDocument;
}

// ---------------------------------------------------------------------------
// Hostname extraction (CodeQL-safe: use URL API, not substring matching)
// ---------------------------------------------------------------------------

/**
 * Extract hostnames from OpenAPI server objects.
 *
 * Uses `new URL()` for parsing — string substring operations on URLs are
 * insufficient for security decisions (js/incomplete-url-substring-sanitization).
 * Only the `hostname` property is captured; port, path, and query are discarded.
 */
export function extractServerHostnames(servers: OpenApiServer[]): string[] {
  const seen = new Set<string>();
  for (const server of servers) {
    if (typeof server.url !== "string" || !server.url) {
      continue;
    }
    try {
      const parsed = new URL(server.url);
      if (parsed.hostname) {
        seen.add(parsed.hostname);
      }
    } catch {
      // Skip malformed URLs silently — codegen continues with remaining servers
    }
  }
  return [...seen];
}

// ---------------------------------------------------------------------------
// Operation slug derivation
// ---------------------------------------------------------------------------

/**
 * Derive a URL-safe, lowercase slug for an operation.
 *
 * Preference order:
 *   1. `operationId` from the spec (lowercased, non-alphanumeric → hyphen)
 *   2. `{httpMethod}-{path-normalized}` (path params stripped)
 */
export function deriveOperationSlug(method: string, urlPath: string, operationId?: string): string {
  if (operationId && operationId.trim()) {
    // Lowercase and replace non-alphanumeric runs with hyphens
    return operationId
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-|-$/g, "");
  }
  // Normalize path: remove leading slash, replace / and {} chars with hyphen
  const normalizedPath = urlPath
    .replace(/^\//, "")
    .replace(/\{[^}]+\}/g, "param")
    .replace(/[^a-z0-9]+/gi, "-")
    .toLowerCase()
    .replace(/^-|-$/g, "");
  return `${method.toLowerCase()}-${normalizedPath || "root"}`;
}

/**
 * Convert a slug like `get-contact-id` to a camelCase identifier: `getContactId`.
 */
export function slugToCamelCase(slug: string): string {
  return slug.replace(/-([a-z0-9])/gi, (_, ch: string) => ch.toUpperCase());
}

/**
 * Convert a slug to PascalCase: `GetContactId`.
 */
export function slugToPascalCase(slug: string): string {
  const camel = slugToCamelCase(slug);
  return camel.charAt(0).toUpperCase() + camel.slice(1);
}

// ---------------------------------------------------------------------------
// Schema extraction
// ---------------------------------------------------------------------------

/**
 * Extract a JSON Schema from parameters and optional requestBody.
 * Only path, query, and header parameters are included in the request schema.
 */
function buildRequestSchema(
  parameters: OpenApiParameter[] | undefined,
  requestBody: OpenApiRequestBody | undefined
): Record<string, unknown> {
  const properties: Record<string, unknown> = {};
  const required: string[] = [];

  for (const param of parameters ?? []) {
    if (!param.name) continue;
    properties[param.name] = {
      ...(param.schema ?? { type: "string" }),
      description: param.description,
    };
    if (param.required) {
      required.push(param.name);
    }
  }

  if (requestBody?.content) {
    const jsonContent =
      requestBody.content["application/json"] ?? Object.values(requestBody.content)[0];
    if (jsonContent?.schema) {
      properties["body"] = jsonContent.schema;
    }
  }

  const schema: Record<string, unknown> = { type: "object", properties };
  if (required.length > 0) {
    schema["required"] = required;
  }
  return schema;
}

/**
 * Extract the response schema from the 200/201/default response.
 */
function buildResponseSchema(
  responses: Record<string, OpenApiResponse> | undefined
): Record<string, unknown> | undefined {
  if (!responses) return undefined;
  const response = responses["200"] ?? responses["201"] ?? responses["default"];
  if (!response?.content) return undefined;
  const jsonContent = response.content["application/json"] ?? Object.values(response.content)[0];
  return jsonContent?.schema ?? undefined;
}

// ---------------------------------------------------------------------------
// Manifest generation
// ---------------------------------------------------------------------------

export interface ParsedOperation {
  slug: string;
  camelName: string;
  method: string;
  path: string;
  /** Names of parameters with `in: "path"` — must be interpolated into the URL. */
  pathParams: string[];
  /** Names of parameters with `in: "query"` — appended as ?key=value. */
  queryParams: string[];
  /** Whether the operation has a request body (POST/PUT/PATCH). */
  hasBody: boolean;
  description?: string;
  requestSchema: Record<string, unknown>;
  responseSchema?: Record<string, unknown>;
}

/**
 * Merge path-item level parameters with operation-level parameters.
 *
 * OpenAPI 3.x §4.8.9: parameters defined on the path item apply to ALL
 * operations under that path. Operation-level parameters override path-item
 * parameters that share the same (name, in) tuple.
 */
function mergeParameters(
  pathItemParams: OpenApiParameter[] | undefined,
  operationParams: OpenApiParameter[] | undefined
): OpenApiParameter[] {
  const base = pathItemParams ?? [];
  const overrides = operationParams ?? [];
  const overrideKeys = new Set(overrides.map((p) => `${p.name}::${p.in}`));
  return [...base.filter((p) => !overrideKeys.has(`${p.name}::${p.in}`)), ...overrides];
}

/**
 * Extract all operations from an OpenAPI document.
 *
 * Path-item level parameters (OpenAPI §4.8.9) are merged with operation-level
 * parameters so that shared parameters (e.g. a path `{id}` defined once on
 * the path item) are correctly reflected in the generated URL interpolation
 * and request schema.
 */
export function extractOperations(spec: OpenApiDocument): ParsedOperation[] {
  const ops: ParsedOperation[] = [];
  const HTTP_METHODS = ["get", "post", "put", "patch", "delete"] as const;

  for (const [urlPath, pathItem] of Object.entries(spec.paths ?? {})) {
    const pathItemParams = pathItem.parameters;

    for (const method of HTTP_METHODS) {
      const operation: OpenApiOperation | undefined = pathItem[method];
      if (!operation) continue;

      const slug = deriveOperationSlug(method, urlPath, operation.operationId);
      const camelName = slugToCamelCase(slug);

      // Merge path-item parameters (shared) with operation parameters (specific)
      const mergedParams = mergeParameters(pathItemParams, operation.parameters);

      ops.push({
        slug,
        camelName,
        method: method.toUpperCase(),
        path: urlPath,
        pathParams: mergedParams.filter((p) => p.in === "path").map((p) => p.name),
        queryParams: mergedParams.filter((p) => p.in === "query").map((p) => p.name),
        hasBody: !!operation.requestBody,
        description: operation.summary ?? operation.description,
        requestSchema: buildRequestSchema(mergedParams, operation.requestBody),
        responseSchema: buildResponseSchema(operation.responses) ?? undefined,
      });
    }
  }

  return ops;
}

/**
 * Build the connector.json manifest from an OpenAPI document.
 */
export function openApiToConnectorManifest(
  spec: OpenApiDocument,
  opts: { name: string; version: string; publisher?: string }
): Record<string, unknown> {
  const servers = spec.servers ?? [];
  const declaredEgress = extractServerHostnames(servers);

  const operations: Record<string, ConnectorOperationDef> = {};
  for (const op of extractOperations(spec)) {
    const def: ConnectorOperationDef = {
      description: op.description,
      requestSchema: op.requestSchema,
    };
    if (op.responseSchema) {
      def.responseSchema = op.responseSchema;
    }
    operations[op.slug] = def;
  }

  const manifest: Record<string, unknown> = {
    schema_version: "1.0",
    name: opts.name,
    version: opts.version,
    connector_type: "api",
    trust_tier: "standard",
    data_license: "UNLICENSED",
    sublicense_required: false,
    data_tier: "information",
    declared_egress: declaredEgress,
    // air_gap_eligible is derived from declared_egress at validation time (T15)
    // — do NOT set it in the generator
    residency: "any",
    ssrf: {
      allowed_domains: declaredEgress,
    },
    operations,
  };

  if (opts.publisher) {
    manifest["publisher"] = opts.publisher;
  }

  return manifest;
}

// ---------------------------------------------------------------------------
// Publish-time SSRF re-validation
// ---------------------------------------------------------------------------

/** Reads a manifest field as a string array, or undefined if absent/not an array. */
function readStringArrayField(
  manifest: Record<string, unknown>,
  field: string
): string[] | undefined {
  const raw = manifest[field];
  if (!Array.isArray(raw)) {
    return undefined;
  }
  for (const d of raw) {
    if (typeof d !== "string") {
      throw new Error(`connector.json: ${field} contains a non-string value: ${JSON.stringify(d)}`);
    }
  }
  return raw as string[];
}

export interface RevalidateSsrfOptions {
  /**
   * The connector's egress hostnames, re-derived right now from its actual
   * OpenAPI spec (`extractServerHostnames` over a freshly re-parsed spec —
   * see `connector publish --spec`). When provided, this is used as the
   * widening baseline INSTEAD of `declared_egress` read off `manifest`
   * itself. That distinction matters: `declared_egress` lives in the same
   * hand-editable `connector.json` as `ssrf.allowed_domains`, so comparing
   * one manifest field against another manifest field only ever proves the
   * file is internally consistent, never that it matches reality — a editor
   * can move both fields together. A value re-derived from the spec, by
   * contrast, cannot be moved by editing `connector.json` alone.
   */
  trustedDeclaredEgress?: string[];
}

/**
 * Re-validate a connector manifest's SSRF egress allowlist immediately before
 * publish.
 *
 * `openApiToConnectorManifest` derives both `declared_egress` and
 * `ssrf.allowed_domains` from the same OpenAPI `servers` list at generation
 * time, so the two are identical when a manifest is freshly generated. A
 * manifest can be hand-edited after generation, though, and nothing re-checks
 * it before it reaches the registry.
 *
 * connector-host's deploy route resolves the allowlist it actually enforces
 * with its own fallback precedence — `ssrf.allowed_domains`, then a top-level
 * `allowed_domains`, then `declared_egress` — so this re-runs the
 * forbidden-value check against whichever value is actually in effect under
 * that same precedence, then confirms that effective value has not been
 * widened beyond a baseline.
 *
 * Without `opts.trustedDeclaredEgress`, that baseline is `declared_egress`
 * read off the same manifest being validated. This only ever catches a
 * hand-edit to `ssrf.allowed_domains` (or a new top-level `allowed_domains`)
 * made in isolation — an edit that moves `declared_egress` to match is
 * invisible to this check by construction, since both values then come from
 * the same file and trivially agree. Passing `opts.trustedDeclaredEgress`
 * (from re-parsing the connector's actual OpenAPI spec — see
 * `connector publish --spec`) closes that gap, because the baseline can no
 * longer be moved by editing `connector.json` alone.
 *
 * A manifest with none of `ssrf.allowed_domains`/top-level `allowed_domains`/
 * `declared_egress` (e.g. a stub-mode `connector init` with no `--spec`)
 * declares no egress allowlist and is left untouched here.
 */
export function revalidateSsrfAllowedDomainsAtPublish(
  manifest: Record<string, unknown>,
  opts: RevalidateSsrfOptions = {}
): void {
  const ssrf = manifest["ssrf"];
  const ssrfAllowedDomains =
    typeof ssrf === "object" && ssrf !== null
      ? readStringArrayField(ssrf as Record<string, unknown>, "allowed_domains")
      : undefined;
  const topLevelAllowedDomains = readStringArrayField(manifest, "allowed_domains");
  const declaredEgress = readStringArrayField(manifest, "declared_egress");

  const effectiveAllowedDomains =
    ssrfAllowedDomains && ssrfAllowedDomains.length > 0
      ? ssrfAllowedDomains
      : topLevelAllowedDomains && topLevelAllowedDomains.length > 0
        ? topLevelAllowedDomains
        : declaredEgress;

  if (!effectiveAllowedDomains || effectiveAllowedDomains.length === 0) {
    return;
  }

  validateSsrfAllowedDomains(effectiveAllowedDomains);

  // The widening baseline: a value re-derived, right now, from outside
  // connector.json wins whenever available — see RevalidateSsrfOptions above
  // for why declared_egress alone cannot serve the same purpose.
  //
  // An empty array is a meaningful baseline, not a missing one — it says the
  // trusted source (the spec's "servers", or connector.json's own
  // declared_egress) declares NO legitimate egress hosts, so every entry in
  // effectiveAllowedDomains is "widened" beyond it. Only actual absence
  // (undefined) means there's nothing to compare against.
  const baseline = opts.trustedDeclaredEgress ?? declaredEgress;
  if (baseline === undefined) {
    return;
  }

  const baselineSet = new Set(baseline);
  const widened = effectiveAllowedDomains.filter((d) => !baselineSet.has(d));
  if (widened.length === 0) {
    return;
  }

  if (opts.trustedDeclaredEgress) {
    throw new Error(
      `connector.json: allowed egress domains widened beyond what the connector's OpenAPI spec ` +
        `actually declares: ${widened.join(", ")}. Update the spec's "servers" list and regenerate ` +
        `with 'connector init --spec' if these hosts are legitimate.`
    );
  }
  throw new Error(
    `connector.json: allowed egress domains widened beyond declared_egress: ${widened.join(", ")}. ` +
      `The SSRF allowlist may not exceed what was declared at generation time — ` +
      `regenerate with 'connector init --spec' to update declared_egress if the connector's ` +
      `OpenAPI spec legitimately added these servers. Note: this check compares connector.json's ` +
      `own fields against each other and cannot detect declared_egress itself being edited to ` +
      `match a widened allowlist — pass --spec to 'connector publish' to re-derive a baseline ` +
      `directly from the OpenAPI spec instead, which closes that gap.`
  );
}

// ---------------------------------------------------------------------------
// Code generation
// ---------------------------------------------------------------------------

function generateConnectorPackageJson(name: string, version: string): string {
  const pkg = {
    name: `connector-${name}`,
    version,
    type: "commonjs",
    scripts: {
      build: "tsc",
      start: "node dist/connector.js",
    },
    dependencies: {
      "@novaos/connector-sdk": "workspace:*",
    },
    devDependencies: {
      typescript: "5.8.3",
    },
  };
  return JSON.stringify(pkg, null, 2) + "\n";
}

function generateTsConfig(): string {
  const tsconfig = {
    compilerOptions: {
      target: "CommonJS",
      module: "CommonJS",
      moduleResolution: "node",
      strict: true,
      outDir: "dist",
      rootDir: "src",
      declaration: true,
      esModuleInterop: true,
    },
    include: ["src/**/*"],
  };
  return JSON.stringify(tsconfig, null, 2) + "\n";
}

function generateOperationFile(op: ParsedOperation): string {
  const hasInputProps =
    op.requestSchema.properties && Object.keys(op.requestSchema.properties as object).length > 0;
  const inputType = hasInputProps ? "Record<string, unknown>" : "Record<string, never>";

  // Build the URL template line:
  //   1. Start from op.path and substitute {param} placeholders using path params
  //   2. Append query params via URLSearchParams when the method is GET/DELETE
  let urlParts = op.path;
  for (const p of op.pathParams) {
    // Replace {paramName} with a template-literal substitution
    urlParts = urlParts.replace(`{${p}}`, `\${String(input["${p}"] ?? "")}`);
  }
  // Emit the server base as a placeholder — connector-host injects the real origin
  const urlExpr = `\`\${ctx.baseUrl ?? ""}${urlParts}\``;

  // Query-string construction for GET / DELETE (body-less) operations
  const queryBlock =
    op.queryParams.length > 0 && (op.method === "GET" || op.method === "DELETE")
      ? [
          `  const _qs = new URLSearchParams();`,
          ...op.queryParams.map(
            (q) => `  if (input["${q}"] != null) _qs.set("${q}", String(input["${q}"]));`
          ),
          `  const _qstr = _qs.toString();`,
          `  const _url = _qstr ? \`\${${urlExpr.slice(1, -1)}}?\${_qstr}\` : ${urlExpr};`,
        ].join("\n")
      : "";
  const finalUrl = queryBlock ? "_url" : urlExpr;

  // Body line: use input["body"] (the nested request body field) — NOT the whole input object
  const bodyLine =
    op.hasBody && op.method !== "GET" && op.method !== "DELETE"
      ? `      body: JSON.stringify(input["body"] ?? {}),`
      : "";

  return `${GENERATED_HEADER}
${GENERATED_BLOCK_START}
import type { ConnectorContext } from "@novaos/connector-sdk";

/**
 * ${op.description ?? op.slug} — ${op.method} ${op.path}
 *
 * Generated from operationId / path: ${op.slug}
 */
export async function ${op.camelName}(
  ctx: ConnectorContext,
  input: ${inputType}
): Promise<unknown> {
${queryBlock ? queryBlock + "\n" : ""}  const response = await ctx.fetch(
    ${finalUrl},
    {
      method: "${op.method}",
      headers: {
        "Content-Type": "application/json",
        Authorization: ctx.credentials.accessToken
          ? \`Bearer \${ctx.credentials.accessToken}\`
          : \`Bearer \${ctx.credentials.apiKey ?? ""}\`,
      },
${bodyLine ? bodyLine + "\n" : ""}    }
  );
  return response.json();
}
${GENERATED_BLOCK_END}
`;
}

function generateConnectorTs(name: string, version: string, operations: ParsedOperation[]): string {
  const className = slugToPascalCase(name.replace(/[^a-z0-9]/gi, "-")) + "Connector";

  const operationImports = operations
    .map((op) => `import { ${op.camelName} } from "./operations/${op.slug}.js";`)
    .join("\n");

  const methodImpls = operations
    .map(
      (
        op
      ) => `  async ${op.camelName}(ctx: ConnectorContext, input: Record<string, unknown>): Promise<unknown> {
    return ${op.camelName}(ctx, input);
  }`
    )
    .join("\n\n");

  return `${GENERATED_HEADER}
${GENERATED_BLOCK_START}
import { DataSourceClient } from "@novaos/connector-sdk";
import type { ConnectorContext } from "@novaos/connector-sdk";

${operationImports}

export class ${className} extends DataSourceClient {
  constructor() {
    super({ name: ${JSON.stringify(name)}, version: ${JSON.stringify(version)} });
  }

${methodImpls}
}

export default ${className};
${GENERATED_BLOCK_END}
`;
}

// ---------------------------------------------------------------------------
// Merge-safe write
// ---------------------------------------------------------------------------

/**
 * Write a file with merge-safe semantics.
 *
 * Three cases:
 *   1. File does not exist → write fresh.
 *   2. File exists with no `@generated` markers → fully custom, skip overwrite.
 *   3. File exists with `@generated` markers → extract content BEFORE the start
 *      marker and AFTER the end marker, then re-inject them around the new
 *      generated block. This preserves any hand-written code outside the block.
 */
function writeMergeSafe(filePath: string, content: string): "written" | "skipped" {
  if (!existsSync(filePath)) {
    writeFileSync(filePath, content, "utf-8");
    return "written";
  }

  const existing = readFileSync(filePath, "utf-8");

  const startIdx = existing.indexOf(GENERATED_BLOCK_START);
  const endIdx = existing.indexOf(GENERATED_BLOCK_END);

  // If the file has no generated markers at all, it is fully custom — skip overwrite
  if (startIdx === -1 && endIdx === -1) {
    return "skipped";
  }

  // Extract the generated block from the new content
  const newStartIdx = content.indexOf(GENERATED_BLOCK_START);
  const newEndIdx = content.indexOf(GENERATED_BLOCK_END);
  if (newStartIdx === -1 || newEndIdx === -1) {
    // Incoming content has no markers — write it wholesale
    writeFileSync(filePath, content, "utf-8");
    return "written";
  }

  const newGeneratedBlock = content.slice(newStartIdx, newEndIdx + GENERATED_BLOCK_END.length);

  // Preserve everything before the existing @generated:start and after @generated:end
  const prefix = startIdx > 0 ? existing.slice(0, startIdx) : "";
  const suffix = endIdx !== -1 ? existing.slice(endIdx + GENERATED_BLOCK_END.length) : "";

  const merged = prefix + newGeneratedBlock + suffix;
  writeFileSync(filePath, merged, "utf-8");
  return "written";
}

// ---------------------------------------------------------------------------
// Main entry point
// ---------------------------------------------------------------------------

export interface OpenApiCodegenOptions {
  name: string;
  publisher?: string;
  specPath: string;
  directory?: string;
}

/**
 * Generate a full connector package from an OpenAPI 3.x spec.
 *
 * Returns `{ directory, files }` in the same shape as `connectorInit`.
 * Throws if:
 *   - the spec file cannot be parsed
 *   - the spec is not OpenAPI 3.x
 *   - any server URL resolves to a forbidden SSRF target
 */
export function initFromOpenApiSpec(opts: OpenApiCodegenOptions): {
  directory: string;
  files: string[];
} {
  const { name, specPath } = opts;

  // Security: reject path traversal in the output directory
  const rawDir = opts.directory ?? `./${name}`;
  assertNoPathTraversal(rawDir, "Output directory");
  const targetDir = path.resolve(rawDir);

  // Parse the spec
  const spec = parseOpenApiSpec(specPath);

  const version = spec.info.version ?? "1.0.0";
  const operations = extractOperations(spec);

  // Build and validate the connector.json manifest (SSRF check at generation time)
  const manifest = openApiToConnectorManifest(spec, { name, version, publisher: opts.publisher });

  // validateConnectorManifest throws on SSRF violations before any file is written
  validateConnectorManifest(manifest);

  // Create directory structure
  mkdirSync(path.join(targetDir, "src", "operations"), { recursive: true });

  const written: string[] = [];

  // connector.json (always overwrite — it is fully generated)
  writeFileSync(
    path.join(targetDir, MANIFEST_FILENAME),
    JSON.stringify(manifest, null, 2) + "\n",
    "utf-8"
  );
  written.push(MANIFEST_FILENAME);

  // tsconfig.json
  const tsconfigPath = path.join(targetDir, "tsconfig.json");
  if (writeMergeSafe(tsconfigPath, generateTsConfig()) === "written") {
    written.push("tsconfig.json");
  }

  // package.json
  const packageJsonPath = path.join(targetDir, "package.json");
  if (writeMergeSafe(packageJsonPath, generateConnectorPackageJson(name, version)) === "written") {
    written.push("package.json");
  }

  // src/connector.ts
  const connectorTsPath = path.join(targetDir, "src", "connector.ts");
  const connectorTsContent = generateConnectorTs(name, version, operations);
  if (writeMergeSafe(connectorTsPath, connectorTsContent) === "written") {
    written.push("src/connector.ts");
  }

  // src/operations/<slug>.ts
  for (const op of operations) {
    const opFilePath = path.join(targetDir, "src", "operations", `${op.slug}.ts`);
    const opContent = generateOperationFile(op);
    if (writeMergeSafe(opFilePath, opContent) === "written") {
      written.push(`src/operations/${op.slug}.ts`);
    }
  }

  return { directory: rawDir, files: written };
}
